  for (var wi = 0; wi < WORLD_READ_ONLY_APIS.length; wi += 1) {
    (function(name){
      window[name] = function(){ readOnly(); return Promise.resolve(undefined); };
    })(WORLD_READ_ONLY_APIS[wi]);
  }

  window.getCharName = function(){ return CHAR_NAME; };
